'use strict';
const el=id=>document.getElementById(id);
const mission={data:null,prediction:null,node:null,clues:new Set(),contextMode:'full',repair:'candidate',report:null,before:null,investigation:null,investigationHistory:[],image:null,busy:false};
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const nodeHypothesis={'prod-backups':'prod-public','staging-backups':'staging-public','preview-service':'service-role','app-service':'service-role'};
const nodeDescription={internet:'This request has no authenticated identity. Public object reads bypass application sign-in controls in this declared local model.','preview-service':'The new document preview feature needs public website assets. Inspect its scope: a public preview does not make every bucket public.','app-service':'The application is a legitimate reader. A repair must preserve its authorized backup access, not simply deny every request.','prod-backups':'Customer backup records must stay private. Look for the storage grant and the independent data-handling requirement.','public-assets':'Website images are intentionally public. A repair that blocks these images breaks the application’s declared behavior.','staging-backups':'Staging data is a separate resource. Check the exact bucket before assuming a change affects every environment.'};
function message(text,error=false){el('mission-message').textContent=text;el('mission-message').classList.toggle('error',error);}
async function api(path,data){const response=await fetch('/api/mission'+path,data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});let value;try{value=await response.json();}catch{throw new Error('The local server did not return a mission response. Start the current Python server and retry.');}if(!response.ok)throw new Error(value.error||'The mission request could not complete.');return value;}
function busy(value){mission.busy=value;document.body.classList.toggle('busy',value);el('run-check').disabled=value||!mission.prediction;el('ask-subq').disabled=value||!mission.data;el('verify-repair').disabled=value||mission.repair==='candidate';for(const control of document.querySelectorAll('.hypothesis-option,.repair-option,[data-context],.artifact-top input,#mission-screenshot,#remove-screenshot'))control.disabled=value;}
function progress(step){document.querySelectorAll('.progress-step').forEach(item=>{const n=Number(item.dataset.step);item.classList.toggle('active',n===step);item.classList.toggle('complete',n<step);});}
function setPrediction(id){if(mission.busy)return;mission.prediction=id;document.querySelectorAll('.hypothesis-option').forEach(button=>{const selected=button.dataset.hypothesis===id;button.classList.toggle('selected',selected);button.setAttribute('aria-pressed',String(selected));});const h=mission.data.hypotheses.find(h=>h.id===id);el('prediction-note').textContent='Your prediction: '+(h?.label||id)+'. The access checks will test it.';if(!mission.report){el('edge-internet-prod').classList.toggle('hypothesized',id==='prod-public');}busy(false);}
function renderHypotheses(){el('hypothesis-options').innerHTML=mission.data.hypotheses.map(h=>`<button class="hypothesis-option" data-hypothesis="${escape(h.id)}" aria-pressed="false"><i aria-hidden="true"></i><span>${escape(h.label)}</span></button>`).join('');document.querySelectorAll('[data-hypothesis]').forEach(button=>button.addEventListener('click',()=>setPrediction(button.dataset.hypothesis)));}
function inspectNode(id){if(!mission.data)return;mission.node=id;document.querySelectorAll('[data-node]').forEach(node=>node.classList.toggle('selected',node.dataset.node===id));const data=mission.data.nodes.find(n=>n.id===id);el('inspector-category').textContent=(data?.kind||'SOURCE EVIDENCE').toUpperCase();el('inspector-title').textContent=data?.label||id;el('inspector-description').textContent=nodeDescription[id]||data?.subtitle||'Inspect the supporting artifacts.';const artifacts=mission.data.artifacts.filter(a=>a.node===id);el('node-artifacts').innerHTML=artifacts.map(a=>`<button data-open-artifact="${escape(a.id)}">${escape(a.id)} · ${escape(a.label)}</button>`).join('');el('node-artifacts').querySelectorAll('[data-open-artifact]').forEach(button=>button.addEventListener('click',()=>openArtifact(button.dataset.openArtifact)));el('predict-node').hidden=!nodeHypothesis[id];}
function openArtifact(id){const artifact=mission.data.artifacts.find(a=>a.id===id);if(!artifact)return;el('source-view').hidden=false;el('source-title').textContent=`${artifact.id} · ${artifact.path}`;el('source-content').textContent=(typeof artifact.content==='string'?artifact.content:JSON.stringify(artifact.content,null,2)).split('\n').map((line,i)=>`${String(i+1).padStart(3)}  ${line}`).join('\n');el('source-view').scrollIntoView({behavior:reducedMotion()?'auto':'smooth',block:'nearest'});}
function renderArtifacts(){const scores=new Map((mission.investigation?.evidence||[]).map(a=>[a.id,a.probability]));el('artifact-grid').innerHTML=mission.data.artifacts.map(a=>{const score=scores.get(a.id);return `<article class="artifact-card ${mission.clues.has(a.id)?'selected':''} ${score>=.5?'model-relevant':''}"><div class="artifact-top"><span>${escape(a.id)}</span><label><input type="checkbox" data-clue="${escape(a.id)}" ${mission.clues.has(a.id)?'checked':''} aria-label="Include ${escape(a.label)} as a clue"> My clue</label></div><button class="artifact-open" data-open-artifact="${escape(a.id)}"><strong>${escape(a.label)}</strong><small>${escape(a.path)}</small></button>${score!==undefined?`<span class="artifact-probability">SubQ relevance · ${(score*100).toFixed(0)}%</span>`:''}</article>`;}).join('');el('artifact-grid').querySelectorAll('[data-open-artifact]').forEach(button=>button.addEventListener('click',()=>openArtifact(button.dataset.openArtifact)));el('artifact-grid').querySelectorAll('[data-clue]').forEach(input=>input.addEventListener('change',()=>{input.checked?mission.clues.add(input.dataset.clue):mission.clues.delete(input.dataset.clue);el('clue-count').textContent=mission.clues.size;input.closest('.artifact-card').classList.toggle('selected',input.checked);if(mission.contextMode==='selected')invalidateInvestigation('Selected clues changed. Ask SubQ again to evaluate this evidence.');}));}
function invalidateInvestigation(note){mission.investigation=null;el('subq-output').hidden=true;el('subq-output').textContent='';document.querySelectorAll('.evidence-highlight').forEach(node=>node.classList.remove('evidence-highlight'));document.querySelectorAll('.repair-option.recommended').forEach(node=>node.classList.remove('recommended'));renderArtifacts();if(note)message(note);}
function renderRepairs(){el('repair-options').innerHTML=mission.data.repairs.map((repair,i)=>`<button class="repair-option" data-repair="${escape(repair.id)}" aria-pressed="false"><span>OPTION ${String(i+1).padStart(2,'0')}<i aria-hidden="true"></i></span><strong>${escape(repair.title)}</strong><p>${escape(repair.description)}</p></button>`).join('');document.querySelectorAll('[data-repair]').forEach(button=>button.addEventListener('click',()=>selectRepair(button.dataset.repair)));}
function selectRepair(id){if(mission.busy)return;mission.repair=id;const repair=mission.data.repairs.find(r=>r.id===id);document.querySelectorAll('[data-repair]').forEach(button=>{button.classList.toggle('selected',button.dataset.repair===id);button.setAttribute('aria-pressed',String(button.dataset.repair===id));});el('repair-diff').hidden=false;el('repair-diff').textContent=typeof repair.diff==='string'?repair.diff:JSON.stringify(repair.diff,null,2);el('repair-selection-note').textContent=repair.title+' selected. This change is only proposed until you verify it.';el('verify-repair').disabled=false;invalidateInvestigation('Prepared repair selected. Ask SubQ to reassess it, or execute the same checks to verify it.');el('subq-tag').textContent='PROPOSED REPAIR';el('mission-outcome').hidden=true;}
function reducedMotion(){return window.matchMedia('(prefers-reduced-motion: reduce)').matches;}
async function investigate(){if(mission.busy||!mission.data)return;busy(true);message(mission.repair==='candidate'?'SubQ is weighing the evidence across the case. The model prediction cannot override an access check.':'SubQ is reassessing the proposed repair against the same requirements.');el('subq-tag').textContent='READING CONTEXT';try{const payload={clues:[...mission.clues],context_mode:mission.contextMode,repair:mission.repair};if(mission.image)payload.images=[mission.image];const result=await api('/investigate',payload);mission.investigation=result;mission.investigationHistory.push({repair:mission.repair,context_mode:mission.contextMode,clues:[...mission.clues],result});el('subq-output').hidden=false;if(result.source!=='live'){el('subq-output').innerHTML=`<div class="subq-error">${escape(result.error||'SubQ is unavailable. No probabilities were fabricated. You can still execute the independent checks.')}</div>`;el('subq-tag').textContent='UNAVAILABLE';message('SubQ could not complete this investigation. Independent access checks remain available.',true);return;}const scope=mission.repair==='candidate'?'CANDIDATE CHANGE':'PROPOSED REPAIR';el('subq-tag').textContent='LIVE RESULT';el('subq-output').innerHTML=`<div class="probability-panel"><div class="eyebrow">${scope} · MODEL PREDICTIONS</div>${result.hypotheses.map(h=>`<div class="probability-row"><div class="probability-label"><span>${escape(h.label)}</span><strong>${(h.probability*100).toFixed(1)}%</strong></div><div class="probability-track"><div class="probability-fill" style="width:${Math.max(0,Math.min(100,h.probability*100))}%"></div></div></div>`).join('')}<div class="subq-usage">${escape(result.model)} · ${(result.latency_ms/1000).toFixed(2)}s<br>${Number(result.usage.input_tokens).toLocaleString()} actual input tokens · ${result.coverage.files}/${result.coverage.total_files} artifacts<br>Next check: ${escape(result.next_check)}${result.screenshot_probability!==null&&result.screenshot_probability!==undefined?'<br>Screenshot corroboration: '+(result.screenshot_probability*100).toFixed(0)+'% (advisory)':''}<br>Predictions guide inspection. Checks determine the outcome.</div></div>`;renderArtifacts();document.querySelectorAll('[data-node]').forEach(node=>{const relevant=result.evidence.filter(e=>e.probability>=.5).some(e=>mission.data.artifacts.find(a=>a.id===e.id)?.node===node.dataset.node);node.classList.toggle('evidence-highlight',relevant);});document.querySelectorAll('[data-repair]').forEach(button=>button.classList.toggle('recommended',button.dataset.repair===result.suggested_repair));const highest=[...result.hypotheses].sort((a,b)=>b.probability-a.probability)[0];message(`${highest.id==='insufficient'?'Need more evidence. ':''}Live SubQ decision: ${highest.label} (${(highest.probability*100).toFixed(1)}%). ${result.coverage.mode==='selected'?'Only your selected clues were supplied.':'Complete eligible case context was supplied.'} Run the access checks to verify.`);}catch(error){el('subq-tag').textContent='UNAVAILABLE';message(error.message,true);}finally{busy(false);}}
function renderMap(report){const buckets=report.state?.buckets||{};const exposed=buckets['prod-backups']?.public_read===true;const authorized=(buckets['prod-backups']?.readers||[]).includes('app-service');el('cloud-map').classList.remove('running');const prod=document.querySelector('[data-node="prod-backups"]');prod.classList.toggle('is-exposed',exposed);prod.classList.toggle('is-secured',!exposed);el('prod-badge').textContent=exposed?'PUBLIC READ VERIFIED':'PUBLIC READ DENIED';el('edge-internet-prod').classList.remove('hypothesized');el('edge-internet-prod').classList.toggle('exposed',exposed);el('edge-internet-prod').classList.toggle('blocked',!exposed);el('path-state').hidden=false;el('path-state').classList.toggle('blocked',!exposed);el('path-state').textContent=exposed?'ANONYMOUS OBJECT READ · ALLOWED':'ANONYMOUS OBJECT READ · DENIED';el('edge-app-prod').classList.toggle('secured',authorized);el('edge-app-prod').classList.toggle('disabled',!authorized);const publicAsset=buckets['public-assets']?.public_read===true;el('edge-internet-assets').classList.toggle('secured',publicAsset);el('edge-internet-assets').classList.toggle('disabled',!publicAsset);document.querySelector('[data-node="public-assets"]').classList.toggle('is-secured',publicAsset);el('map-status').className='map-status '+(report.won?'secured':'exposed');el('map-status').innerHTML='<i></i>'+escape(report.won?'Boundary verified':exposed?'Exposure reproduced':'Service regression found');}
function renderReport(report){el('verification-section').hidden=false;const passed=report.checks.filter(c=>c.passed).length;const failures=report.checks.filter(c=>!c.passed);const unauthorized=failures.filter(c=>c.expected==='DENIED'&&c.actual==='ALLOWED');const broken=failures.filter(c=>c.expected==='ALLOWED'&&c.actual==='DENIED');el('verification-title').textContent=report.won?'The repair passed the contract.':report.repair==='candidate'?'The exposure is reproducible.':'The repair did not pass.';el('verification-summary').innerHTML=`<div class="summary-card ${report.won?'safe':'danger'}"><small>FROZEN CONTRACT</small><strong>${passed} / ${report.checks.length}</strong><p>Independent access checks passed</p></div><div class="summary-card ${unauthorized.length?'danger':'safe'}"><small>UNAUTHORIZED ACCESS</small><strong>${unauthorized.length?'REPRODUCED':'BLOCKED'}</strong><p>${unauthorized.length} failing forbidden-access checks</p></div><div class="summary-card ${broken.length?'danger':'safe'}"><small>LEGITIMATE APPLICATION</small><strong>${broken.length?'BROKEN':'WORKING'}</strong><p>${broken.length?broken.length+' functional regressions':'Required access remains available'}</p></div>`;el('checks-list').innerHTML=report.checks.map(check=>`<details class="check-item ${check.passed?'':'failed'}"><summary>${escape(check.label)}<span>${check.passed?'PASS':'FAIL'} · ${escape(check.actual)}</span></summary><p>Request: ${escape(check.actor)} → ${escape(check.resource)}\nExpected: ${escape(check.expected)}\nObserved: ${escape(check.actual)}\n\n${escape((check.trace||[]).join('\n'))}</p></details>`).join('');el('contract-fingerprint').textContent=`Frozen contract · ${report.contract_hash}\nEvaluated configuration · ${report.candidate_hash}\nSame contract for every repair. Local declared access semantics; not a full cloud IAM assessment.`;renderMap(report);}
async function runCheck(repaired=false){if(mission.busy||!mission.prediction)return;busy(true);el('cloud-map').classList.add('running');message(repaired?'Applying the prepared change in an isolated simulation, then executing the same frozen checks…':'Executing actual local access decisions for anonymous users and authorized services…');progress(repaired?3:2);try{const [report]=await Promise.all([api('/check',{hypothesis:mission.prediction,repair:repaired?mission.repair:'candidate'}),new Promise(resolve=>setTimeout(resolve,reducedMotion()?0:950))]);mission.report=report;if(!repaired)mission.before=report;renderReport(report);el('repair-section').hidden=false;message(report.summary);if(repaired){el('mission-outcome').hidden=false;el('mission-outcome').className='mission-outcome '+(report.won?'':'failed');el('mission-outcome').innerHTML=`<span class="outcome-symbol">${report.won?'✳':'↻'}</span><div><div class="eyebrow">${report.won?'MISSION COMPLETE · VERIFIED':'KEEP INVESTIGATING'}</div><h2>${report.won?'Leak closed. App still works.':'A fix has to do both.'}</h2><p>${escape(report.summary)} ${report.won?'The unauthorized path is closed, and legitimate access still passes the same contract.':'Inspect the failing checks, select another repair, and try again.'}</p></div><button class="quiet-button" id="outcome-action">${report.won?'Replay mission ↻':'Choose another repair ↑'}</button>`;el('outcome-action').addEventListener('click',()=>report.won?resetMission():el('repair-section').scrollIntoView({behavior:reducedMotion()?'auto':'smooth'}));el('mission-outcome').scrollIntoView({behavior:reducedMotion()?'auto':'smooth',block:'center'});}else{progress(3);el('verification-section').scrollIntoView({behavior:reducedMotion()?'auto':'smooth',block:'start'});}}catch(error){message(error.message,true);}finally{el('cloud-map').classList.remove('running');busy(false);}}
function exportEvidence(){if(!mission.report)return;const evidence={mission:mission.data.id,fixture_origin:'Authored fictional local simulation',prediction:mission.prediction,subq:mission.investigation,subq_history:mission.investigationHistory,before:mission.before,after:mission.report,scope:'No cloud resources changed. Model predictions are advisory; the independent frozen access contract decides the outcome.'};const url=URL.createObjectURL(new Blob([JSON.stringify(evidence,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='blindspot-stop-the-leak-evidence.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function resetMission(){if(mission.busy)return;location.reload();}
async function init(){try{mission.data=await api('');el('mission-story').textContent=mission.data.story;renderHypotheses();renderRepairs();renderArtifacts();el('artifact-count').textContent=`${mission.data.artifacts.length} complete source artifacts · read-only`;el('context-caption').textContent=`${mission.data.context.files} complete artifacts · ~${Number(mission.data.context.estimated_tokens).toLocaleString()} estimated source tokens`;el('ask-subq').disabled=false;el('subq-tag').textContent=mission.data.model_available?'LIVE MODEL':'KEY NEEDED';message('Mission ready. Explore the cloud map, make a prediction, and reproduce the access decision.');}catch(error){message(error.message,true);}}
document.querySelectorAll('[data-node]').forEach(node=>node.addEventListener('click',()=>inspectNode(node.dataset.node)));el('predict-node').addEventListener('click',()=>{if(nodeHypothesis[mission.node])setPrediction(nodeHypothesis[mission.node]);});el('view-change').addEventListener('click',()=>{if(mission.data){const artifact=mission.data.artifacts.find(a=>/change|diff|pull.?request/i.test(a.path+' '+a.label))||mission.data.artifacts[0];openArtifact(artifact.id);}});el('close-source').addEventListener('click',()=>el('source-view').hidden=true);el('run-check').addEventListener('click',()=>runCheck(false));el('verify-repair').addEventListener('click',()=>runCheck(true));el('ask-subq').addEventListener('click',investigate);el('export-evidence').addEventListener('click',exportEvidence);el('reset-mission').addEventListener('click',resetMission);document.querySelectorAll('[data-context]').forEach(button=>button.addEventListener('click',()=>{if(mission.busy)return;mission.contextMode=button.dataset.context;document.querySelectorAll('[data-context]').forEach(b=>b.classList.toggle('selected',b===button));el('context-caption').textContent=mission.contextMode==='full'?`${mission.data.context.files} complete artifacts · no source summaries`:'Only your checked case files will be supplied. Missing evidence can change the decision.';invalidateInvestigation('Context scope changed. Ask SubQ again to compare its decision.');}));el('mission-screenshot').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2*1024*1024){message('Use a PNG, JPEG, or WebP screenshot under 2 MiB.',true);event.target.value='';return;}try{const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});mission.image={mediaType:file.type,base64};el('remove-screenshot').hidden=false;document.querySelector('label[for="mission-screenshot"]').textContent='✓ Screenshot attached';invalidateInvestigation('Screenshot attached for SubQ’s next investigation. Images are advisory evidence, not access proof.');}catch{message('The screenshot could not be read.',true);}});el('remove-screenshot').addEventListener('click',()=>{mission.image=null;el('mission-screenshot').value='';el('remove-screenshot').hidden=true;document.querySelector('label[for="mission-screenshot"]').innerHTML='＋ Console screenshot <small>optional</small>';invalidateInvestigation('Screenshot removed.');});init();
